#include <stdio.h>
#include <stdlib.h>

#define INF 4000000000000000000LL

int cmp(const void *a, const void *b) {
    int ia = *(const int*)a;
    int ib = *(const int*)b;
    return (ia > ib) - (ia < ib);
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    int *T = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &T[i]);
    }
    qsort(T, N, sizeof(int), cmp);

    long long *dp_next = (long long*)malloc((K + 1) * sizeof(long long));
    long long *dp_next2 = (long long*)malloc((K + 1) * sizeof(long long));
    long long *dp_cur = (long long*)malloc((K + 1) * sizeof(long long));

    for (int j = 0; j <= K; j++) {
        dp_next[j] = INF;
        dp_next2[j] = INF;
    }
    dp_next[0] = 0;

    for (int i = N; i >= 1; i--) {
        for (int j = 0; j <= K; j++) {
            dp_cur[j] = dp_next[j];
            if (i <= N - 1 && j >= 1) {
                if (i + 3 * j <= N + 1) {
                    long long diff = (long long)T[i] - T[i - 1];
                    long long cost = diff * diff;
                    if (dp_next2[j - 1] != INF) {
                        long long val = dp_next2[j - 1] + cost;
                        if (val < dp_cur[j]) {
                            dp_cur[j] = val;
                        }
                    }
                }
            }
        }
        // shift arrays
        for (int j = 0; j <= K; j++) {
            dp_next2[j] = dp_next[j];
            dp_next[j] = dp_cur[j];
        }
    }

    printf("%lld\n", dp_next[K]);

    free(T);
    free(dp_next);
    free(dp_next2);
    free(dp_cur);
    return 0;
}
